'use strict'

// Generated by vfs_scaffold_auth. The /auth routes: sign-up, login, logout, the current user, and user management
// for admins. Error messages are deliberately generic where a detail would help an attacker.

const crypto = require('node:crypto')
const express = require('express')
const config = require('./config')
const store = require('./store')
const sessions = require('./sessions')
const { hashPassword, verifyPassword, needsRehash, verifyAgainstDummy } = require('./password')
const { createLimiter } = require('./rateLimit')

const EMAIL = /^[^\s@]{1,64}@[^\s@]{1,255}\.[^\s@]{2,}$/
const MIN_PASSWORD = 8
const MAX_PASSWORD = 256
const INVITE_DAYS = 7
const WINDOW_MS = 15 * 60 * 1000

// Failed logins: a few per address+email, a few more per email from anywhere.
const perClient = createLimiter({ max: 5, windowMs: WINDOW_MS })
const perEmail = createLimiter({ max: 20, windowMs: WINDOW_MS })

class HttpError extends Error {
  constructor(status, message) {
    super(message)
    this.status = status
  }
}

const wrap = (handler) => (req, res, next) => Promise.resolve(handler(req, res, next)).catch(next)
const normalizeEmail = (value) => (typeof value === 'string' ? value.trim().toLowerCase() : '')
const publicUser = (user) => ({ id: user.id, email: user.email, name: user.name, roles: user.roles, disabled: Boolean(user.disabled), createdAt: user.createdAt })

function readCredentials(body) {
  const email = normalizeEmail(body.email)
  const password = typeof body.password === 'string' ? body.password : ''
  if (!EMAIL.test(email) || email.length > 320) throw new HttpError(400, 'Enter a valid email address')
  if (password.length < MIN_PASSWORD || password.length > MAX_PASSWORD) {
    throw new HttpError(400, `The password must be ${MIN_PASSWORD} to ${MAX_PASSWORD} characters long`)
  }
  return { email, password }
}

function readRoles(value) {
  if (!Array.isArray(value) || value.some((role) => typeof role !== 'string' || !config.roles.includes(role))) {
    throw new HttpError(400, `roles must be a list of: ${config.roles.join(', ')}`)
  }
  return [...new Set(value)]
}

const defaultRoles = () => (config.defaultRole ? [config.defaultRole] : [])

/** Who gets which roles at sign-up. Runs inside the store's transaction, so "first user" is race-free. */
function rolesForSignup({ isFirst, invite, email }) {
  if (isFirst) return { roles: [...new Set([config.adminRole, ...defaultRoles()])] }
  if (config.signup === 'invite') {
    if (!invite || (invite.email && invite.email !== email)) return { error: 'INVITE_INVALID' }
    return { roles: invite.roles.length ? invite.roles : defaultRoles() }
  }
  return { roles: defaultRoles() }
}

async function currentUser(req, res) {
  if (req.user === undefined) req.user = await sessions.loadUser(req, res)
  return req.user
}

function requireUser(req, res, next) {
  currentUser(req, res)
    .then((user) => (user ? next() : res.status(401).json({ error: 'Sign in to continue' })))
    .catch(next)
}

function requireRole(...wanted) {
  const roles = wanted.flat()
  return (req, res, next) => {
    currentUser(req, res)
      .then((user) => {
        if (!user) return res.status(401).json({ error: 'Sign in to continue' })
        if (!roles.some((role) => user.roles.includes(role))) return res.status(403).json({ error: 'You do not have access to this' })
        return next()
      })
      .catch(next)
  }
}

function createAuthRouter() {
  const router = express.Router()
  const admin = requireRole(config.adminRole)

  router.use((req, res, next) => {
    res.set('Cache-Control', 'no-store')
    // Writes must be JSON: a cross-site HTML form cannot send that without a CORS preflight.
    if (!['GET', 'HEAD', 'OPTIONS'].includes(req.method) && !req.is('application/json')) {
      return res.status(415).json({ error: 'Send the request body as application/json' })
    }
    return next()
  })
  router.use(express.json({ limit: '16kb' }))
  router.use((req, _res, next) => store.ready().then(() => next(), next))

  router.post('/signup', wrap(async(req, res) => {
    const body = req.body || {}
    const { email, password } = readCredentials(body)
    const name = typeof body.name === 'string' ? body.name.trim().slice(0, 120) || null : null
    const inviteCode = typeof body.inviteCode === 'string' ? body.inviteCode.trim() : ''
    const passwordHash = await hashPassword(password)
    const result = await store.createUser({
      email,
      name,
      passwordHash,
      inviteHash: inviteCode ? sessions.hashToken(inviteCode) : null,
      assignRoles: ({ isFirst, invite }) => rolesForSignup({ isFirst, invite, email }),
    })
    if (result.error === 'EMAIL_TAKEN') throw new HttpError(409, 'An account with this email already exists')
    if (result.error === 'INVITE_INVALID') {
      throw new HttpError(403, inviteCode ? 'This invite code is not valid or was already used' : 'Sign-up needs an invite code')
    }
    await sessions.startSession(req, res, result.user.id)
    res.status(201).json({ user: publicUser(result.user) })
  }))

  router.post('/login', wrap(async(req, res) => {
    const body = req.body || {}
    const email = normalizeEmail(body.email)
    const password = typeof body.password === 'string' ? body.password.slice(0, MAX_PASSWORD) : ''
    const clientKey = `${req.ip}|${email}`
    for (const check of [perClient.check(clientKey), perEmail.check(email)]) {
      if (!check.allowed) {
        res.set('Retry-After', String(check.retryAfterSeconds))
        throw new HttpError(429, 'Too many attempts. Try again in a few minutes')
      }
    }
    const account = email ? await store.findUserByEmail(email) : null
    const valid = account ? await verifyPassword(password, account.passwordHash) : await verifyAgainstDummy(password)
    if (!account || !valid || account.disabled) {
      perClient.fail(clientKey)
      perEmail.fail(email)
      throw new HttpError(401, 'Email or password is incorrect')
    }
    perClient.reset(clientKey)
    if (needsRehash(account.passwordHash)) await store.setPasswordHash(account.id, await hashPassword(password))
    await sessions.startSession(req, res, account.id)
    res.json({ user: publicUser(await store.getUser(account.id)) })
  }))

  router.post('/logout', wrap(async(req, res) => {
    await sessions.endSession(req, res)
    res.json({ ok: true })
  }))

  // 200 with `user: null` when signed out, so a page asking "who am I?" does not log an error.
  router.get('/me', wrap(async(req, res) => {
    const user = await currentUser(req, res)
    res.json({
      user: user ? { id: user.id, email: user.email, name: user.name, roles: user.roles } : null,
      signup: config.signup,
      needsSetup: user ? false : (await store.countUsers()) === 0,
    })
  }))

  router.get('/roles', admin, (_req, res) => res.json({ roles: config.roles, adminRole: config.adminRole, defaultRole: config.defaultRole }))

  router.get('/users', admin, wrap(async(_req, res) => {
    res.json({ users: (await store.listUsers()).map(publicUser) })
  }))

  router.patch('/users/:id', admin, wrap(async(req, res) => {
    const id = Number(req.params.id)
    if (!Number.isSafeInteger(id) || id < 1) throw new HttpError(400, 'Invalid user id')
    const body = req.body || {}
    const changes = {}
    if (body.roles !== undefined) changes.roles = readRoles(body.roles)
    if (body.disabled !== undefined) {
      if (typeof body.disabled !== 'boolean') throw new HttpError(400, 'disabled must be true or false')
      changes.disabled = body.disabled
    }
    if (!Object.keys(changes).length) throw new HttpError(400, 'Nothing to change: send roles and/or disabled')
    const result = await store.updateUser(id, changes, config.adminRole)
    if (result.error === 'NOT_FOUND') throw new HttpError(404, 'User not found')
    if (result.error === 'LAST_ADMIN') throw new HttpError(409, 'At least one active admin must remain')
    if (changes.disabled) await store.deleteUserSessions(id)
    res.json({ user: publicUser(result.user) })
  }))

  router.post('/invites', admin, wrap(async(req, res) => {
    if (config.signup !== 'invite') throw new HttpError(400, 'Sign-up is open: invites are not needed')
    const body = req.body || {}
    const email = body.email === undefined || body.email === '' ? null : normalizeEmail(body.email)
    if (email !== null && !EMAIL.test(email)) throw new HttpError(400, 'Enter a valid email address')
    const roles = body.roles === undefined ? defaultRoles() : readRoles(body.roles)
    const code = crypto.randomBytes(18).toString('base64url')
    const expiresAt = new Date(Date.now() + INVITE_DAYS * 24 * 60 * 60 * 1000)
    await store.createInvite({ codeHash: sessions.hashToken(code), email, roles, createdBy: req.user.id, expiresAt })
    res.status(201).json({ code, email, roles, expiresAt: expiresAt.toISOString() })
  }))

  // eslint-disable-next-line no-unused-vars -- Express recognises an error handler by its four parameters
  router.use((error, _req, res, _next) => {
    if (error instanceof HttpError) return res.status(error.status).json({ error: error.message })
    if (error && error.type === 'entity.parse.failed') return res.status(400).json({ error: 'The request body is not valid JSON' })
    if (error && error.type === 'entity.too.large') return res.status(413).json({ error: 'The request body is too large' })
    console.error('[auth]', error)
    return res.status(500).json({ error: 'Something went wrong. Try again' })
  })

  return router
}

module.exports = { createAuthRouter, requireUser, requireRole, currentUser, rolesForSignup, HttpError }
